def wrap_html(text:str)->str:
 text=re.sub(r'<header>.*?</header>',NAV,text,count=1,flags=re.S)
 if NAV not in text:text=text.replace('<main>',NAV+'<main>',1)
 text=text.replace('</style>',SHELL_CSS+STATS_CSS+DESKTOP_CSS+DESKTOP_MATCH_MOBILE_CSS+ARTICLE_CSS+'</style>',1);text=re.sub(r'<footer>.*?</footer>',FOOTER,text,count=1,flags=re.S)
 if FOOTER not in text:text.replace('</main>','</main>'+FOOTER,1)
 return text
def filter_script(selector):return f'''<script>function filterCatalog(q){{q=q.toLowerCase().trim();document.querySelectorAll('{selector}').forEach(function(x){{x.style.display=!q||x.textContent.toLowerCase().includes(q)?'':'none';}});}}</script>'''
def cancer_index(root):
 items=[]
 for key in sorted(g.DISEASE_INFO):
  label=g.display_name(key);slug=g.slugify(key);items.append(f'<div class="catalog-card"><strong>{g.esc(label)}</strong><div class="catalog-links"><a href="{SITE}/north-america/dogs/{slug}/">Dogs</a><a href="{SITE}/north-america/cats/{slug}/">Cats</a></div></div>')
 body=f'''<h1>Cancer Types</h1><p class="lead catalog-intro"><strong>Start with your pet’s diagnosis.</strong> Choose a cancer type below to see a plain-language overview, standard treatment options and current clinical trials for dogs or cats. If you are not sure of the exact diagnosis, use the Clinical Trial Finder and enter what you know.</p><input class="catalog-search" type="search" placeholder="Search cancer type" aria-label="Search cancer types" oninput="filterCatalog(this.value)"><div class="catalog-grid">{''.join(items)}</div>{filter_script('.catalog-card')}''';d=root/'cancer-types';d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(g.page('Cancer Types | Vet Trial Finder','Browse dog and cat cancer types with current treatment studies and clinical trial listings.',body,f'{SITE}/cancer-types/'),encoding='utf-8')
def other_treatments(root):
 body=f'''<h1>Other Cancer Treatment Options</h1><p class="lead catalog-intro"><strong>Some cancer treatments are difficult to find even when they are already being used in veterinary oncology.</strong> This section collects selected options beyond routine surgery, chemotherapy and radiation, including treatments available only at certain hospitals or through special programs.</p><div class="site-grid"><a class="site-card" href="{FINDER.rstrip('/')}/Additional_Oncology_Options"><h3>Electrochemotherapy</h3><p>Find veterinary centers that offer ECT outside clinical trials.</p></a><a class="site-card" href="{FINDER}"><h3>Advanced Treatments</h3><p>Selected newer or less widely available oncology treatments.</p></a><a class="site-card" href="{FINDER}"><h3>Expanded Access</h3><p>Programs that may provide access to treatment outside a standard clinical trial.</p></a></div><p>These options are not appropriate for every cancer or every pet. Use the listings to find a center or program, then confirm details with the treating team.</p><p><a href="{SITE}/articles/electrochemotherapy/">Read our guide to electrochemotherapy</a></p>''';d=root/'other-treatments';d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(g.page('Other Veterinary Cancer Treatments | Vet Trial Finder','Electrochemotherapy, advanced treatment options and expanded access programs for dogs and cats with cancer.',body,f'{SITE}/other-treatments/'),encoding='utf-8')

